is_shown = {
 always = no # retired common-fund entry

  is_ai = no is_alive = yes is_imprisoned = no
  save_temporary_scope_as = mam_rv_resume_actor
  OR = {
   has_variable = mam_rv_open_file
   title:h_china = { any_in_list = { variable = mam_rv_files mam_revenue_file_current_trigger = yes
    exists = var:mam_rv_next_actor var:mam_rv_next_actor = scope:mam_rv_resume_actor
   } }
  }
 }

is_shown = {
 always = no # retired common-fund entry
 scope:actor = { mam_revenue_officer_trigger = yes is_ai = no } scope:recipient = { mam_revenue_recipient_trigger = yes this != scope:actor } }

is_shown = {
 always = no # retired common-fund entry
 scope:actor = { mam_revenue_officer_trigger = yes is_ai = no exists = var:mam_rv_designated_recipient }
  scope:recipient = { mam_revenue_ministry_trigger = yes }
 }

