is_shown = {
 always = no # retired common-fund entry

  scope:actor = { is_ai = no mam_revenue_can_appeal_trigger = yes }
  scope:recipient = {
   OR = { mam_revenue_emperor_trigger = yes mam_revenue_chancellor_trigger = yes }
   this != scope:actor
  }
 }

is_shown = {
		scope:recipient = {
			has_treasury = yes
			this != scope:actor
			top_liege ?= scope:actor.top_liege
		}
	}

is_shown = {
		scope:recipient = {
			has_treasury = yes
			this != scope:actor
			trigger_if = {
				limit = {
					vassal_contract_has_flag = celestial_military_appointment
					title:e_minister_of_war.holder ?= scope:actor
				}
				top_liege = scope:actor.top_liege
			}
			trigger_else_if = {
				limit = {
					NOT = { vassal_contract_has_flag = celestial_military_appointment }
					title:e_minister_of_revenue.holder ?= scope:actor
				}
				top_liege = scope:actor.top_liege
			}
			trigger_else = {
				is_vassal_or_below_of = scope:actor
			}
		}
	}

is_shown = {
		scope:actor = {
			OR = {
				has_title = title:e_minister_of_war
				has_title = title:e_minister_of_revenue
				this = scope:recipient.top_liege
			}
		}
		scope:recipient = {
			top_liege ?= scope:actor.top_liege
			has_treasury = yes
			trigger_if = {
				limit = {
					title:e_minister_of_revenue.holder ?= scope:actor
					NOT = { vassal_contract_has_flag = celestial_military_appointment }
				}
			}
			trigger_else_if = {
				limit = {
					title:e_minister_of_war.holder ?= scope:actor
					vassal_contract_has_flag = celestial_military_appointment
				}
			}
			trigger_else = {
				top_liege = scope:actor
			}
		}
	}

is_shown = {
		NOT = { AND = { mam_revenue_native_request_trigger = yes scope:actor = { is_ai = no } } }
		scope:actor = {
			this != scope:recipient
		}
		scope:actor.top_liege ?= scope:recipient.top_liege
		scope:recipient = {
			government_has_flag = government_is_celestial
			OR = {
				this = scope:actor.top_liege
				OR = {
					AND = {
						has_title = title:e_minister_of_war
						liege ?= {
							highest_held_title_tier >= tier_hegemony
							government_has_flag = government_is_celestial
						}
						scope:actor = {
							vassal_contract_has_flag = celestial_military_appointment
						}
					}
					AND = {
						has_title = title:e_minister_of_revenue
						liege ?= {
							highest_held_title_tier >= tier_hegemony
							government_has_flag = government_is_celestial
						}
						scope:actor = {
							NOT = { vassal_contract_has_flag = celestial_military_appointment }
						}
					}
				}
			}
			trigger_if = {
				limit = {
					scope:actor = { is_ai = yes }
				}
				NOT = { has_variable = celestial_request_treasury_ai_cooldown }
			}
		}
	}
